import { requireActor } from '@/server/auth/guard';
import { errorResponse } from '@/server/http/errors';
import { resolveTeaserImage } from '@/server/opportunities/teaser-image';

export const dynamic = 'force-dynamic';
export const runtime = 'nodejs';

type Context = { params: Promise<{ id: string }> };

/**
 * Teaser image: any ENABLED user may see a PUBLISHED opportunity's image; its
 * seller and BACKOFFICE may see it in any status; everyone else gets 404.
 * The seed SVG is generated by the server (not by users), so it is safe to
 * serve inline under a locked-down CSP. Uploaded images redirect (302) to a
 * 60 s signed URL.
 */
export async function GET(_req: Request, { params }: Context): Promise<Response> {
  try {
    const actor = await requireActor();
    const { id } = await params;
    const image = await resolveTeaserImage(actor, id);
    if (image.kind === 'redirect') {
      return new Response(null, {
        status: 302,
        headers: {
          Location: image.url,
          'Cache-Control': 'no-store, private',
          'Referrer-Policy': 'no-referrer',
        },
      });
    }
    return new Response(image.body, {
      status: 200,
      headers: {
        'Content-Type': 'image/svg+xml',
        'Content-Security-Policy': "default-src 'none'; style-src 'unsafe-inline'",
        'X-Content-Type-Options': 'nosniff',
        'Content-Disposition': 'inline',
        'Cache-Control': 'private, max-age=300',
      },
    });
  } catch (err) {
    return errorResponse(err);
  }
}
